SourceCode.Declaration:
class TFMResponseElement
{
    str                         responseText;
    str                         innerXML;
    TFMRequestElement           originalRequest;
    TFMDocumentDeviceId         deviceId;
    TFMPageID                   pageId;
    TFMCommandResponses         commands;
}

Method.Source:
public str parmResponseText(str _responseText = responseText)
{
    responseText = _responseText;
    return responseText;
}

public str parmInnerXML(str _innerXML = innerXML)
{
    innerXML = _innerXML;
    return innerXML;
}

public void addCommandResponse(TFMCommandResponse _command)
{
    if (!commands)
    {
        commands = TFMCommandResponses::Construct();
    }
    commands.addCommandResponse(_command);
}

public TFMRequestElement parmOriginalRequest(TFMRequestElement _originalRequest = originalRequest)
{
    originalRequest = _originalRequest;
    return originalRequest;
}

public XmlDocument getXML()
{
    XmlDocument         returnXML = new XmlDocument();
    XmlElement          tmpRootElement          = returnXML.createElement('responseData');
    this.appendToXML(tmpRootElement);
    if (commands)
    {
        commands.appendToXML(tmpRootElement);
    }
    returnXML.appendChild(tmpRootElement);
    return returnXML;
}

public TFMDocumentDeviceId parmDeviceId(TFMDocumentDeviceId _deviceId = deviceId)
{
    deviceId = _deviceId;
    return deviceId;        
}
